import test,{after} from 'node:test';
import assert from 'node:assert/strict';
import {wholeSourcePartitionRows,validateWholeStockCertificate,stockCertificateDiagnostics} from '../../tools/review/whole-source-stock-certificate.mjs';
import {sceneCompileDiagnostics} from '../../workbenches/furnished-house/scene.js';
