const grid={origin:[0,0,0],pitch:[.5,1.06,.5]},evidence=[];limitDiagnosticTrialSteps(64);
const surface=(id,owner,quantity,finish=null)=>({id,sourceCarrierId:owner,fuelAmount:quantity,finish,triangles:[[[.125,0,.125],[.125,0,.875],[.875,0,.875]],[[.125,0,.125],[.875,0,.875],[.875,0,.125]]]}),canonical=(id,q=2)=>({id,fuelAmount:q,fuelClass:'clapboard',finish:null});
after(()=>console.log('PARTITION_CERTIFICATE_SYNTHETIC '+JSON.stringify({evidence,diagnostics:stockCertificateDiagnostics(),compiler:sceneCompileDiagnostics(),trial:trialDiagnostics(),actualSavedCertificates:0,sourceTransforms:0})));
test('whole source aggregation preserves owner quantity, finish and per-surface envelopes',()=>{const sources=[surface('a','owner',1),surface('b','owner',.75,{fuelClass:'lacquer',amount:.25})],rows=wholeSourcePartitionRows(sources,[{id:'owner',nativeQuantity:2}],grid);assert.equal(rows.length,1);assert.equal(rows[0].sourceQuantity,2);assert.equal(rows[0].sourceCount,2);assert.equal(rows[0].partitionError.epsilon,1e-7);assert.equal(rows[0].partitionError.surfaces.length,2);for(const k of ['positive','negative','roundoffBound'])assert.equal(rows[0].partitionError[k],rows[0].partitionError.surfaces.reduce((n,s)=>n+s[k],0));assert.ok(rows[0].partitionError.surfaces.every(s=>s.candidateTriangleCells===8&&s.sourceArea>0));evidence.push({control:'exact-owner-aggregation',rows});});
test('generated local certificate accepts positive drift without committing or normalizing raw stock',()=>{const rows=wholeSourcePartitionRows([surface('source','owner',2)],[{id:'owner',nativeQuantity:2}],grid),row=rows[0];row.nativeQuantity=2+row.partitionError.positive/2;const before=JSON.stringify(rows),gate=validateWholeStockCertificate([canonical('owner')],rows);assert.equal(gate.status,'NUMERICAL_GATE_PASS');assert.equal(gate.before.activeInitial,0);assert.equal(gate.after.activeInitial,0);assert.equal(gate.after.coldReserve,2);assert.equal(gate.committed,false);assert.equal(JSON.stringify(rows),before);evidence.push({control:'positive-drift',rows,gate});});
test('certificate present rejects positive and negative overrun, wrong input, invalid epsilon and batch mismatch',()=>{const base=wholeSourcePartitionRows([surface('source','owner',2)],[{id:'owner',nativeQuantity:2}],grid),cases=[];for(const direction of [1,-1]){const rows=structuredClone(base),p=rows[0].partitionError,bound=direction>0?p.positive:p.negative;rows[0].nativeQuantity=2+direction*2*(bound+64*Number.EPSILON*2);const gate=validateWholeStockCertificate([canonical('owner')],rows);assert.equal(gate.status,'NUMERICAL_GATE_REJECTED');assert.match(gate.error.message,/quantity differs/);cases.push({direction,gate});}for(const [kind,change] of [['input',r=>r.sourceQuantity+=.01],['epsilon',r=>r.partitionError.epsilon=1e-6]]){const rows=structuredClone(base);change(rows[0]);const gate=validateWholeStockCertificate([canonical('owner')],rows);assert.equal(gate.status,'NUMERICAL_GATE_REJECTED');cases.push({kind,gate});}const batch=validateWholeStockCertificate([canonical('owner')],base,3);assert.equal(batch.status,'NUMERICAL_GATE_REJECTED');assert.match(batch.error.message,/batch quantity mismatch/);evidence.push({control:'numerical-refusals',cases,batch});});
test('a present zero allowance overrides fallback and a missing certificate cannot use it',()=>{const rows=wholeSourcePartitionRows([surface('source','owner',2)],[{id:'owner',nativeQuantity:2+1e-7}],grid),r=rows[0];r.partitionError.positive=r.partitionError.negative=r.partitionError.roundoffBound=0;const present=validateWholeStockCertificate([canonical('owner')],rows);assert.equal(present.certificatePresent,true);assert.equal(present.status,'NUMERICAL_GATE_REJECTED');assert.match(present.error.message,/quantity differs/);delete r.partitionError;const missing=validateWholeStockCertificate([canonical('owner')],rows);assert.equal(missing.status,'NUMERICAL_GATE_REJECTED');assert.match(missing.error.message,/fallback forbidden/);assert.throws(()=>wholeSourcePartitionRows([surface('large','owner',2)],[{id:'owner',nativeQuantity:2}],grid,{maxCells:1}),/geometry bound/);evidence.push({control:'no-fallback',present,missing});});

